-- -----------------------------------
-- Table structure for `qrt_arrange`
-- -----------------------------------

DROP TABLE IF EXISTS `qrt_arrange`;
CREATE TABLE `qrt_arrange` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `user_id` int(50) NOT NULL,
  `qrt_arrangetime` datetime NOT NULL,
  `alert_id` text CHARACTER SET utf8 NOT NULL,
  `comment` varchar(500) CHARACTER SET utf8 DEFAULT NULL,
  `status` int(10) NOT NULL DEFAULT '0' COMMENT '1 wip 2 close',
  `QRT_NAME` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=96529 DEFAULT CHARSET=latin1;

